#[allow(dead_code)]
impl Opcode {
    pub(crate) const fn has_argument(self) -> bool {
        matches!(
            self,
            opcodes::BINARY_OP
                | opcodes::BUILD_INTERPOLATION
                | opcodes::BUILD_LIST
                | opcodes::BUILD_MAP
                | opcodes::BUILD_SET
                | opcodes::BUILD_SLICE
                | opcodes::BUILD_STRING
                | opcodes::BUILD_TUPLE
                | opcodes::CALL
                | opcodes::CALL_INTRINSIC_1
                | opcodes::CALL_INTRINSIC_2
                | opcodes::CALL_KW
                | opcodes::COMPARE_OP
                | opcodes::CONTAINS_OP
                | opcodes::CONVERT_VALUE
                | opcodes::COPY
                | opcodes::COPY_FREE_VARS
                | opcodes::DELETE_ATTR
                | opcodes::DELETE_DEREF
                | opcodes::DELETE_FAST
                | opcodes::DELETE_GLOBAL
                | opcodes::DELETE_NAME
                | opcodes::DICT_MERGE
                | opcodes::DICT_UPDATE
                | opcodes::END_ASYNC_FOR
                | opcodes::EXTENDED_ARG
                | opcodes::FOR_ITER
                | opcodes::GET_AWAITABLE
                | opcodes::IMPORT_FROM
                | opcodes::IMPORT_NAME
                | opcodes::IS_OP
                | opcodes::JUMP_BACKWARD
                | opcodes::JUMP_BACKWARD_NO_INTERRUPT
                | opcodes::JUMP_FORWARD
                | opcodes::LIST_APPEND
                | opcodes::LIST_EXTEND
                | opcodes::LOAD_ATTR
                | opcodes::LOAD_COMMON_CONSTANT
                | opcodes::LOAD_CONST
                | opcodes::LOAD_DEREF
                | opcodes::LOAD_FAST
                | opcodes::LOAD_FAST_AND_CLEAR
                | opcodes::LOAD_FAST_BORROW
                | opcodes::LOAD_FAST_BORROW_LOAD_FAST_BORROW
                | opcodes::LOAD_FAST_CHECK
                | opcodes::LOAD_FAST_LOAD_FAST
                | opcodes::LOAD_FROM_DICT_OR_DEREF
                | opcodes::LOAD_FROM_DICT_OR_GLOBALS
                | opcodes::LOAD_GLOBAL
                | opcodes::LOAD_NAME
                | opcodes::LOAD_SMALL_INT
                | opcodes::LOAD_SPECIAL
                | opcodes::LOAD_SUPER_ATTR
                | opcodes::MAKE_CELL
                | opcodes::MAP_ADD
                | opcodes::MATCH_CLASS
                | opcodes::POP_JUMP_IF_FALSE
                | opcodes::POP_JUMP_IF_NONE
                | opcodes::POP_JUMP_IF_NOT_NONE
                | opcodes::POP_JUMP_IF_TRUE
                | opcodes::RAISE_VARARGS
                | opcodes::RERAISE
                | opcodes::SEND
                | opcodes::SET_ADD
                | opcodes::SET_FUNCTION_ATTRIBUTE
                | opcodes::SET_UPDATE
                | opcodes::STORE_ATTR
                | opcodes::STORE_DEREF
                | opcodes::STORE_FAST
                | opcodes::STORE_FAST_LOAD_FAST
                | opcodes::STORE_FAST_STORE_FAST
                | opcodes::STORE_GLOBAL
                | opcodes::STORE_NAME
                | opcodes::SWAP
                | opcodes::UNPACK_EX
                | opcodes::UNPACK_SEQUENCE
                | opcodes::YIELD_VALUE
                | opcodes::RESUME
        )
    }

    pub(crate) const fn has_constant(self) -> bool {
        matches!(self, opcodes::LOAD_CONST)
    }

    pub(crate) const fn has_name(self) -> bool {
        matches!(
            self,
            opcodes::DELETE_ATTR
                | opcodes::DELETE_GLOBAL
                | opcodes::DELETE_NAME
                | opcodes::IMPORT_FROM
                | opcodes::IMPORT_NAME
                | opcodes::LOAD_ATTR
                | opcodes::LOAD_FROM_DICT_OR_GLOBALS
                | opcodes::LOAD_GLOBAL
                | opcodes::LOAD_NAME
                | opcodes::LOAD_SUPER_ATTR
                | opcodes::STORE_ATTR
                | opcodes::STORE_GLOBAL
                | opcodes::STORE_NAME
        )
    }

    pub(crate) const fn has_jump(self) -> bool {
        matches!(
            self,
            opcodes::END_ASYNC_FOR
                | opcodes::FOR_ITER
                | opcodes::JUMP_BACKWARD
                | opcodes::JUMP_BACKWARD_NO_INTERRUPT
                | opcodes::JUMP_FORWARD
                | opcodes::POP_JUMP_IF_FALSE
                | opcodes::POP_JUMP_IF_NONE
                | opcodes::POP_JUMP_IF_NOT_NONE
                | opcodes::POP_JUMP_IF_TRUE
                | opcodes::SEND
        )
    }

    pub(crate) const fn has_free(self) -> bool {
        matches!(
            self,
            opcodes::DELETE_DEREF
                | opcodes::LOAD_FROM_DICT_OR_DEREF
                | opcodes::MAKE_CELL
                | opcodes::STORE_DEREF
        )
    }

    pub(crate) const fn has_local(self) -> bool {
        matches!(
            self,
            opcodes::BINARY_OP_INPLACE_ADD_UNICODE
                | opcodes::DELETE_FAST
                | opcodes::LOAD_DEREF
                | opcodes::LOAD_FAST
                | opcodes::LOAD_FAST_AND_CLEAR
                | opcodes::LOAD_FAST_BORROW
                | opcodes::LOAD_FAST_BORROW_LOAD_FAST_BORROW
                | opcodes::LOAD_FAST_CHECK
                | opcodes::LOAD_FAST_LOAD_FAST
                | opcodes::STORE_FAST
                | opcodes::STORE_FAST_LOAD_FAST
                | opcodes::STORE_FAST_STORE_FAST
        )
    }
}

#[allow(dead_code)]
pub(crate) const fn is_scope_exit(opcode: Opcode) -> bool {
    matches!(
        opcode,
        opcodes::RETURN_VALUE | opcodes::RAISE_VARARGS | opcodes::RERAISE
    )
}

#[allow(dead_code)]
pub(crate) const fn is_unconditional_jump(opcode: Opcode) -> bool {
    matches!(
        opcode,
        opcodes::JUMP_BACKWARD | opcodes::JUMP_BACKWARD_NO_INTERRUPT | opcodes::JUMP_FORWARD
    )
}

#[allow(dead_code)]
pub(crate) const fn is_conditional_jump(opcode: Opcode) -> bool {
    matches!(
        opcode,
        opcodes::POP_JUMP_IF_FALSE
            | opcodes::POP_JUMP_IF_NONE
            | opcodes::POP_JUMP_IF_NOT_NONE
            | opcodes::POP_JUMP_IF_TRUE
    )
}

