pub(crate) fn num_popped(opcode: Opcode, argument: u32) -> usize {
    let argument = i64::from(argument);
    let value = match opcode {
        opcodes::CACHE => 0,
        opcodes::BINARY_SLICE => 3,
        opcodes::BUILD_TEMPLATE => 2,
        opcodes::BINARY_OP_INPLACE_ADD_UNICODE => 2,
        opcodes::CALL_FUNCTION_EX => 4,
        opcodes::CHECK_EG_MATCH => 2,
        opcodes::CHECK_EXC_MATCH => 2,
        opcodes::CLEANUP_THROW => 3,
        opcodes::DELETE_SUBSCR => 2,
        opcodes::END_FOR => 1,
        opcodes::END_SEND => 2,
        opcodes::EXIT_INIT_CHECK => 1,
        opcodes::FORMAT_SIMPLE => 1,
        opcodes::FORMAT_WITH_SPEC => 2,
        opcodes::GET_AITER => 1,
        opcodes::GET_ANEXT => 1,
        opcodes::GET_ITER => 1,
        opcodes::RESERVED => 0,
        opcodes::GET_LEN => 1,
        opcodes::GET_YIELD_FROM_ITER => 1,
        opcodes::INTERPRETER_EXIT => 1,
        opcodes::LOAD_BUILD_CLASS => 0,
        opcodes::LOAD_LOCALS => 0,
        opcodes::MAKE_FUNCTION => 1,
        opcodes::MATCH_KEYS => 2,
        opcodes::MATCH_MAPPING => 1,
        opcodes::MATCH_SEQUENCE => 1,
        opcodes::NOP => 0,
        opcodes::NOT_TAKEN => 0,
        opcodes::POP_EXCEPT => 1,
        opcodes::POP_ITER => 1,
        opcodes::POP_TOP => 1,
        opcodes::PUSH_EXC_INFO => 1,
        opcodes::PUSH_NULL => 0,
        opcodes::RETURN_GENERATOR => 0,
        opcodes::RETURN_VALUE => 1,
        opcodes::SETUP_ANNOTATIONS => 0,
        opcodes::STORE_SLICE => 4,
        opcodes::STORE_SUBSCR => 3,
        opcodes::TO_BOOL => 1,
        opcodes::UNARY_INVERT => 1,
        opcodes::UNARY_NEGATIVE => 1,
        opcodes::UNARY_NOT => 1,
        opcodes::WITH_EXCEPT_START => 5,
        opcodes::BINARY_OP => 2,
        opcodes::BUILD_INTERPOLATION => 2 + (argument & 1),
        opcodes::BUILD_LIST => argument,
        opcodes::BUILD_MAP => argument * 2,
        opcodes::BUILD_SET => argument,
        opcodes::BUILD_SLICE => argument,
        opcodes::BUILD_STRING => argument,
        opcodes::BUILD_TUPLE => argument,
        opcodes::CALL => 2 + argument,
        opcodes::CALL_INTRINSIC_1 => 1,
        opcodes::CALL_INTRINSIC_2 => 2,
        opcodes::CALL_KW => 3 + argument,
        opcodes::COMPARE_OP => 2,
        opcodes::CONTAINS_OP => 2,
        opcodes::CONVERT_VALUE => 1,
        opcodes::COPY => 1 + (argument - 1),
        opcodes::COPY_FREE_VARS => 0,
        opcodes::DELETE_ATTR => 1,
        opcodes::DELETE_DEREF => 0,
        opcodes::DELETE_FAST => 0,
        opcodes::DELETE_GLOBAL => 0,
        opcodes::DELETE_NAME => 0,
        opcodes::DICT_MERGE => 5 + (argument - 1),
        opcodes::DICT_UPDATE => 2 + (argument - 1),
        opcodes::END_ASYNC_FOR => 2,
        opcodes::EXTENDED_ARG => 0,
        opcodes::FOR_ITER => 1,
        opcodes::GET_AWAITABLE => 1,
        opcodes::IMPORT_FROM => 1,
        opcodes::IMPORT_NAME => 2,
        opcodes::IS_OP => 2,
        opcodes::JUMP_BACKWARD => 0,
        opcodes::JUMP_BACKWARD_NO_INTERRUPT => 0,
        opcodes::JUMP_FORWARD => 0,
        opcodes::LIST_APPEND => 2 + (argument - 1),
        opcodes::LIST_EXTEND => 2 + (argument - 1),
        opcodes::LOAD_ATTR => 1,
        opcodes::LOAD_COMMON_CONSTANT => 0,
        opcodes::LOAD_CONST => 0,
        opcodes::LOAD_DEREF => 0,
        opcodes::LOAD_FAST => 0,
        opcodes::LOAD_FAST_AND_CLEAR => 0,
        opcodes::LOAD_FAST_BORROW => 0,
        opcodes::LOAD_FAST_BORROW_LOAD_FAST_BORROW => 0,
        opcodes::LOAD_FAST_CHECK => 0,
        opcodes::LOAD_FAST_LOAD_FAST => 0,
        opcodes::LOAD_FROM_DICT_OR_DEREF => 1,
        opcodes::LOAD_FROM_DICT_OR_GLOBALS => 1,
        opcodes::LOAD_GLOBAL => 0,
        opcodes::LOAD_NAME => 0,
        opcodes::LOAD_SMALL_INT => 0,
        opcodes::LOAD_SPECIAL => 1,
        opcodes::LOAD_SUPER_ATTR => 3,
        opcodes::MAKE_CELL => 0,
        opcodes::MAP_ADD => 3 + (argument - 1),
        opcodes::MATCH_CLASS => 3,
        opcodes::POP_JUMP_IF_FALSE => 1,
        opcodes::POP_JUMP_IF_NONE => 1,
        opcodes::POP_JUMP_IF_NOT_NONE => 1,
        opcodes::POP_JUMP_IF_TRUE => 1,
        opcodes::RAISE_VARARGS => argument,
        opcodes::RERAISE => 1 + argument,
        opcodes::SEND => 2,
        opcodes::SET_ADD => 2 + (argument - 1),
        opcodes::SET_FUNCTION_ATTRIBUTE => 2,
        opcodes::SET_UPDATE => 2 + (argument - 1),
        opcodes::STORE_ATTR => 2,
        opcodes::STORE_DEREF => 1,
        opcodes::STORE_FAST => 1,
        opcodes::STORE_FAST_LOAD_FAST => 1,
        opcodes::STORE_FAST_STORE_FAST => 2,
        opcodes::STORE_GLOBAL => 1,
        opcodes::STORE_NAME => 1,
        opcodes::SWAP => 2 + (argument - 2),
        opcodes::UNPACK_EX => 1,
        opcodes::UNPACK_SEQUENCE => 1,
        opcodes::YIELD_VALUE => 1,
        opcodes::RESUME => 0,
        _ => unreachable!(
            "missing generated stack metadata for opcode {}",
            opcode.code()
        ),
    };
    usize::try_from(value).expect("negative generated stack-popped count")
}

pub(crate) fn num_pushed(opcode: Opcode, argument: u32) -> usize {
    let argument = i64::from(argument);
    let value = match opcode {
        opcodes::CACHE => 0,
        opcodes::BINARY_SLICE => 1,
        opcodes::BUILD_TEMPLATE => 1,
        opcodes::BINARY_OP_INPLACE_ADD_UNICODE => 0,
        opcodes::CALL_FUNCTION_EX => 1,
        opcodes::CHECK_EG_MATCH => 2,
        opcodes::CHECK_EXC_MATCH => 2,
        opcodes::CLEANUP_THROW => 2,
        opcodes::DELETE_SUBSCR => 0,
        opcodes::END_FOR => 0,
        opcodes::END_SEND => 1,
        opcodes::EXIT_INIT_CHECK => 0,
        opcodes::FORMAT_SIMPLE => 1,
        opcodes::FORMAT_WITH_SPEC => 1,
        opcodes::GET_AITER => 1,
        opcodes::GET_ANEXT => 2,
        opcodes::GET_ITER => 1,
        opcodes::RESERVED => 0,
        opcodes::GET_LEN => 2,
        opcodes::GET_YIELD_FROM_ITER => 1,
        opcodes::INTERPRETER_EXIT => 0,
        opcodes::LOAD_BUILD_CLASS => 1,
        opcodes::LOAD_LOCALS => 1,
        opcodes::MAKE_FUNCTION => 1,
        opcodes::MATCH_KEYS => 3,
        opcodes::MATCH_MAPPING => 2,
        opcodes::MATCH_SEQUENCE => 2,
        opcodes::NOP => 0,
        opcodes::NOT_TAKEN => 0,
        opcodes::POP_EXCEPT => 0,
        opcodes::POP_ITER => 0,
        opcodes::POP_TOP => 0,
        opcodes::PUSH_EXC_INFO => 2,
        opcodes::PUSH_NULL => 1,
        opcodes::RETURN_GENERATOR => 1,
        opcodes::RETURN_VALUE => 1,
        opcodes::SETUP_ANNOTATIONS => 0,
        opcodes::STORE_SLICE => 0,
        opcodes::STORE_SUBSCR => 0,
        opcodes::TO_BOOL => 1,
        opcodes::UNARY_INVERT => 1,
        opcodes::UNARY_NEGATIVE => 1,
        opcodes::UNARY_NOT => 1,
        opcodes::WITH_EXCEPT_START => 6,
        opcodes::BINARY_OP => 1,
        opcodes::BUILD_INTERPOLATION => 1,
        opcodes::BUILD_LIST => 1,
        opcodes::BUILD_MAP => 1,
        opcodes::BUILD_SET => 1,
        opcodes::BUILD_SLICE => 1,
        opcodes::BUILD_STRING => 1,
        opcodes::BUILD_TUPLE => 1,
        opcodes::CALL => 1,
        opcodes::CALL_INTRINSIC_1 => 1,
        opcodes::CALL_INTRINSIC_2 => 1,
        opcodes::CALL_KW => 1,
        opcodes::COMPARE_OP => 1,
        opcodes::CONTAINS_OP => 1,
        opcodes::CONVERT_VALUE => 1,
        opcodes::COPY => 2 + (argument - 1),
        opcodes::COPY_FREE_VARS => 0,
        opcodes::DELETE_ATTR => 0,
        opcodes::DELETE_DEREF => 0,
        opcodes::DELETE_FAST => 0,
        opcodes::DELETE_GLOBAL => 0,
        opcodes::DELETE_NAME => 0,
        opcodes::DICT_MERGE => 4 + (argument - 1),
        opcodes::DICT_UPDATE => 1 + (argument - 1),
        opcodes::END_ASYNC_FOR => 0,
        opcodes::EXTENDED_ARG => 0,
        opcodes::FOR_ITER => 2,
        opcodes::GET_AWAITABLE => 1,
        opcodes::IMPORT_FROM => 2,
        opcodes::IMPORT_NAME => 1,
        opcodes::IS_OP => 1,
        opcodes::JUMP_BACKWARD => 0,
        opcodes::JUMP_BACKWARD_NO_INTERRUPT => 0,
        opcodes::JUMP_FORWARD => 0,
        opcodes::LIST_APPEND => 1 + (argument - 1),
        opcodes::LIST_EXTEND => 1 + (argument - 1),
        opcodes::LOAD_ATTR => 1 + (argument & 1),
        opcodes::LOAD_COMMON_CONSTANT => 1,
        opcodes::LOAD_CONST => 1,
        opcodes::LOAD_DEREF => 1,
        opcodes::LOAD_FAST => 1,
        opcodes::LOAD_FAST_AND_CLEAR => 1,
        opcodes::LOAD_FAST_BORROW => 1,
        opcodes::LOAD_FAST_BORROW_LOAD_FAST_BORROW => 2,
        opcodes::LOAD_FAST_CHECK => 1,
        opcodes::LOAD_FAST_LOAD_FAST => 2,
        opcodes::LOAD_FROM_DICT_OR_DEREF => 1,
        opcodes::LOAD_FROM_DICT_OR_GLOBALS => 1,
        opcodes::LOAD_GLOBAL => 1 + (argument & 1),
        opcodes::LOAD_NAME => 1,
        opcodes::LOAD_SMALL_INT => 1,
        opcodes::LOAD_SPECIAL => 2,
        opcodes::LOAD_SUPER_ATTR => 1 + (argument & 1),
        opcodes::MAKE_CELL => 0,
        opcodes::MAP_ADD => 1 + (argument - 1),
        opcodes::MATCH_CLASS => 1,
        opcodes::POP_JUMP_IF_FALSE => 0,
        opcodes::POP_JUMP_IF_NONE => 0,
        opcodes::POP_JUMP_IF_NOT_NONE => 0,
        opcodes::POP_JUMP_IF_TRUE => 0,
        opcodes::RAISE_VARARGS => 0,
        opcodes::RERAISE => argument,
        opcodes::SEND => 2,
        opcodes::SET_ADD => 1 + (argument - 1),
        opcodes::SET_FUNCTION_ATTRIBUTE => 1,
        opcodes::SET_UPDATE => 1 + (argument - 1),
        opcodes::STORE_ATTR => 0,
        opcodes::STORE_DEREF => 0,
        opcodes::STORE_FAST => 0,
        opcodes::STORE_FAST_LOAD_FAST => 1,
        opcodes::STORE_FAST_STORE_FAST => 0,
        opcodes::STORE_GLOBAL => 0,
        opcodes::STORE_NAME => 0,
        opcodes::SWAP => 2 + (argument - 2),
        opcodes::UNPACK_EX => 1 + (argument & 0xff) + (argument >> 8),
        opcodes::UNPACK_SEQUENCE => argument,
        opcodes::YIELD_VALUE => 1,
        opcodes::RESUME => 0,
        _ => unreachable!(
            "missing generated stack metadata for opcode {}",
            opcode.code()
        ),
    };
    usize::try_from(value).expect("negative generated stack-pushed count")
}
